// QueryServer is the server API for Query service.
type QueryServer interface {
	// Params returns Task parameters.
	Params(context.Context, *QueryTaskParamsRequest) (*QueryTaskParamsResponse, error)
	// Task returns the composite view of one task.
	Task(context.Context, *QueryTaskRequest) (*QueryTaskResponse, error)
	// TaskStage returns the stage and next-deadline projection of one task.
	TaskStage(context.Context, *QueryTaskStageRequest) (*QueryTaskStageResponse, error)
	// TaskAssignment returns the Worker assignment projection of one task.
	TaskAssignment(context.Context, *QueryTaskAssignmentRequest) (*QueryTaskAssignmentResponse, error)
	// AssignmentRandomness returns the frozen assignment randomness of one task.
	AssignmentRandomness(context.Context, *QueryAssignmentRandomnessRequest) (*QueryAssignmentRandomnessResponse, error)
	// TaskBudget returns the authoritative per-task accounting row.
	TaskBudget(context.Context, *QueryTaskBudgetRequest) (*QueryTaskBudgetResponse, error)
	// TaskBuilders returns the frozen Task Builder selection of one task. It is the
	// only read path for the per-task Builder identity that Worker INPUT/OUTPUT
	// transfer, the three-Builder fan-out, the 2-of-3 data-ready confirmation and
	// the two Builder bitmaps all address; PRUNED and post-compaction semantics are
	// frozen on QueryTaskBuildersResponse.
	// TaskBuilders executes the TaskBuilders operation.
	TaskBuilders(context.Context, *QueryTaskBuildersRequest) (*QueryTaskBuildersResponse, error)
	// InferReceipt returns one task's accepted inference receipt.
	InferReceipt(context.Context, *QueryInferReceiptRequest) (*QueryInferReceiptResponse, error)
	// AnchorAudit returns the anchor commitment audit record of one task (ADR-0040).
	AnchorAudit(context.Context, *QueryAnchorAuditRequest) (*QueryAnchorAuditResponse, error)
	// AnchorVotes returns the validator votes and tally of one task's anchor audit (ADR-0040 v4).
	AnchorVotes(context.Context, *QueryAnchorVotesRequest) (*QueryAnchorVotesResponse, error)
	// WorkerEvidence returns one compact objective-evidence receipt.
	WorkerEvidence(context.Context, *QueryWorkerEvidenceRequest) (*QueryWorkerEvidenceResponse, error)
	// VerifierValueEvidence is registered but returns ERR_NOT_ACTIVATED.
	VerifierValueEvidence(context.Context, *QueryVerifierValueEvidenceRequest) (*QueryVerifierValueEvidenceResponse, error)
	// VerifierCandidateWindow returns one round's frozen verifier window.
	VerifierCandidateWindow(context.Context, *QueryVerifierCandidateWindowRequest) (*QueryVerifierCandidateWindowResponse, error)
	// VerifierAssignment returns one round's verifier assignment.
	VerifierAssignment(context.Context, *QueryVerifierAssignmentRequest) (*QueryVerifierAssignmentResponse, error)
	// VerifyCommit returns one verifier's commit row.
	VerifyCommit(context.Context, *QueryVerifyCommitRequest) (*QueryVerifyCommitResponse, error)
	// ResultReceipt returns one verifier's result credential.
	ResultReceipt(context.Context, *QueryResultReceiptRequest) (*QueryResultReceiptResponse, error)
	// DataUnavailableReports pages one round's verifier reports.
	DataUnavailableReports(context.Context, *QueryDataUnavailableReportsRequest) (*QueryDataUnavailableReportsResponse, error)
	// BuilderDataUnavailable returns one (task, round, builder) aggregate.
	BuilderDataUnavailable(context.Context, *QueryBuilderDataUnavailableRequest) (*QueryBuilderDataUnavailableResponse, error)
	// SettlementFacts returns the retained immutable settlement facts.
	SettlementFacts(context.Context, *QuerySettlementFactsRequest) (*QuerySettlementFactsResponse, error)
	// Settlement returns the sole committed settlement state and plan.
	Settlement(context.Context, *QuerySettlementRequest) (*QuerySettlementResponse, error)
	// VerificationRound returns round 1 or round 2 state.
	VerificationRound(context.Context, *QueryVerificationRoundRequest) (*QueryVerificationRoundResponse, error)
	// TaskGasReimbursements pages receipts by (tx_hash, item_index).
	TaskGasReimbursements(context.Context, *QueryTaskGasReimbursementsRequest) (*QueryTaskGasReimbursementsResponse, error)
	// TaskFailureClass returns one task failure classification.
	TaskFailureClass(context.Context, *QueryTaskFailureClassRequest) (*QueryTaskFailureClassResponse, error)
	// EvidenceCleanup returns the bounded cleanup progress of one task.
	EvidenceCleanup(context.Context, *QueryEvidenceCleanupRequest) (*QueryEvidenceCleanupResponse, error)
	// EpochTaskSummary returns the retained immutable receipt. Epoch zero is
	// invalid, an in-progress fold fails precondition, and a missing or pruned
	// receipt is not found. Partial cursor state is never returned.
	EpochTaskSummary(context.Context, *QueryEpochTaskSummaryRequest) (*QueryEpochTaskSummaryResponse, error)
	// Session returns one stream session.
	Session(context.Context, *QuerySessionRequest) (*QuerySessionResponse, error)
	// SessionNonce returns the next nonce for one user.
	SessionNonce(context.Context, *QuerySessionNonceRequest) (*QuerySessionNonceResponse, error)
	// SessionsByOwner lists active sessions for one user.
	SessionsByOwner(context.Context, *QuerySessionsByOwnerRequest) (*QuerySessionsByOwnerResponse, error)
	// SessionTerminalSummary returns one collapsed session summary.
	SessionTerminalSummary(context.Context, *QuerySessionTerminalSummaryRequest) (*QuerySessionTerminalSummaryResponse, error)
	// OrderSequence returns one order sequence audit row.
	OrderSequence(context.Context, *QueryOrderSequenceRequest) (*QueryOrderSequenceResponse, error)
	// RoleActiveTasks lists active tasks for one worker or verifier.
	RoleActiveTasks(context.Context, *QueryRoleActiveTasksRequest) (*QueryRoleActiveTasksResponse, error)
}

